MODULE TRANS_PNM_ARGS_INFO_MOD

USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT

IMPLICIT NONE

PRIVATE
PUBLIC :: ARGS_INFO

! Shapes of the array arguments to TRANS_PNM
TYPE, BIND(C) :: ARGS_INFO
  INTEGER(KIND=C_INT) :: IPRPNM_SHAPE(2)
END TYPE ARGS_INFO

END MODULE TRANS_PNM_ARGS_INFO_MOD

SUBROUTINE TRANS_PNM(KRESOL, KM, PRPNM, LDTRANSPOSE, LDCHEAP)

USE PARKIND1,                    ONLY: JPRB, JPIM
USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT, C_BOOL, C_PTR, C_LOC, C_NULL_PTR
USE TRANS_PNM_ARGS_INFO_MOD,     ONLY: ARGS_INFO

IMPLICIT NONE

INTERFACE
SUBROUTINE TRANS_PNM_CPP_BINDING_SP(ARGS, KRESOL, KM, KTRANSPOSE, KCHEAP, PRPNM) &
  &  BIND(C, NAME="trans_pnm_sp")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_FLOAT, C_INT, C_PTR
  USE TRANS_PNM_ARGS_INFO_MOD, ONLY: ARGS_INFO
  TYPE(ARGS_INFO),               INTENT(IN)  :: ARGS
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KRESOL
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)  :: KM
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KTRANSPOSE
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KCHEAP
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(OUT) :: PRPNM(*)
END SUBROUTINE TRANS_PNM_CPP_BINDING_SP
SUBROUTINE TRANS_PNM_CPP_BINDING_DP(ARGS, KRESOL, KM, KTRANSPOSE, KCHEAP, PRPNM) &
  &  BIND(C, NAME="trans_pnm_dp")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_DOUBLE, C_INT, C_PTR
  USE TRANS_PNM_ARGS_INFO_MOD, ONLY: ARGS_INFO
  TYPE(ARGS_INFO),               INTENT(IN)  :: ARGS
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KRESOL
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)  :: KM
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KTRANSPOSE
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KCHEAP
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(OUT) :: PRPNM(*)
END SUBROUTINE TRANS_PNM_CPP_BINDING_DP
END INTERFACE

INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KRESOL
INTEGER(KIND=JPIM),           INTENT(IN)  :: KM
REAL(KIND=JPRB),    OPTIONAL, INTENT(OUT) :: PRPNM(:,:)
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDTRANSPOSE
LOGICAL,            OPTIONAL, INTENT(IN)  :: LDCHEAP

TYPE(ARGS_INFO) :: ARGS

TYPE(C_PTR) :: KRESOL_PTR, KTRANSPOSE_PTR, KCHEAP_PTR
INTEGER(KIND=C_INT),  TARGET :: IRESOL
LOGICAL(KIND=C_BOOL), TARGET :: LTRANSPOSE, LCHEAP

IF (PRESENT(PRPNM)) THEN
  ARGS%IPRPNM_SHAPE = SHAPE(PRPNM, KIND=C_INT)
ELSE
  ARGS%IPRPNM_SHAPE = 0_C_INT
ENDIF

IF (PRESENT(KRESOL)) THEN
  IRESOL = KRESOL
  KRESOL_PTR = C_LOC(IRESOL)
ELSE
  KRESOL_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(LDTRANSPOSE)) THEN
  LTRANSPOSE = LDTRANSPOSE
  KTRANSPOSE_PTR = C_LOC(LTRANSPOSE)
ELSE
  KTRANSPOSE_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(LDCHEAP)) THEN
  LCHEAP = LDCHEAP
  KCHEAP_PTR = C_LOC(LCHEAP)
ELSE
  KCHEAP_PTR = C_NULL_PTR
ENDIF

#ifdef TRANS_SINGLE
CALL TRANS_PNM_CPP_BINDING_SP(ARGS, KRESOL_PTR, KM, KTRANSPOSE_PTR, KCHEAP_PTR, PRPNM=PRPNM)
#else
CALL TRANS_PNM_CPP_BINDING_DP(ARGS, KRESOL_PTR, KM, KTRANSPOSE_PTR, KCHEAP_PTR, PRPNM=PRPNM)
#endif

END SUBROUTINE TRANS_PNM
